/** Commander exits that are not failures: it already wrote help or version text to stdout itself, so no result frame is owed (rule 3). Every other commander code is a usage error. */
export const COMMANDER_NON_ERRORS: ReadonlySet<string> = new Set(['commander.help', 'commander.helpDisplayed', 'commander.version']);

/** The verb a run was reaching for when it failed before any verb ran: the longest leading non-flag prefix naming a public verb, else the first operand, else the program name. Never empty — a shell parses `verb` as a required string. */
export function attemptedVerb(operands: readonly string[]): string {
  const words: string[] = [];
  for (const t of operands) { if (t.startsWith('-')) break; words.push(t); if (words.length === 2) break; }
  if ((FRAME_VERBS as readonly string[]).includes(words.join(' '))) return words.join(' ');
  return words[0] ?? 'terum-skills';
}
